using System.Text;
using System.Text.Json.Serialization;
namespace HakutaiKagami.Core.Contracts;
public enum CraftAction { MeetGroup,Hire,RenewPay,ResumeGroup,Buy,Sell,Load,Unload,Produce,MeetMerchant,PermitMission,JoinFaith,LaunchVoyage,ReturnVoyage,CollectTradeDebt,CancelVoyage }
public enum CraftSkill { Gunsmith,Mining,Stonework,Foreign }
public sealed record CraftInput(EntityId Id,CraftAction Action,EntityId Owner,EntityId Site,EntityId? Reference=null,EntityId? Destination=null,string Good="iron",long Quantity=1,long AnnualPay=50,bool Housing=true,bool Privileges=true,bool Allow=true);
public sealed record CraftEntry(CraftInput Input,EntityId Actor,long At,long Revision,long Coins,long Rice,long Wood,long Due,bool Accepted,JourneyLeg[] Legs);
public sealed record CraftState(int Schema,string Policy,CraftEntry[] Entries);
public sealed record CraftGroup(EntityId Id,string Name,EntityId Home,CraftSkill Skill,int People,string Basis);
public sealed record CraftPosition(EntityId Group,EntityId? Site,EntityId? Owner,EntityId? Destination,long? ArrivalAt,bool Stopped,string? BlockedEdge);
public sealed record CraftRecipe(string Good,CraftSkill Skill,string[] Materials,long[] Amounts,long Wood,long Coins,long Rice,long Output,long Seconds,WorksKind Facility);
public sealed record CraftVoyage(EntityId Id,EntityId Ship,EntityId Owner,EntityId Port,long Depart,long? ReturnAt,string Phase,string Cargo,long Quantity);
public sealed record MissionOrganization(EntityId Id,EntityId Representative,EntityId Site,string Name,string Basis);
public static partial class CraftTrade
{
 public const string Policy="physical-craft-groups-material-production-local-mission-owned-voyage-v1";
 internal static CraftEntry[] Entries(ContractWorld w)=>w.Crafts?.Entries??[];
 static void Need([System.Diagnostics.CodeAnalysis.DoesNotReturnIf(false)]bool c,string why){if(!c)throw new InvalidDataException(why);}
 static bool Before(CraftEntry e,long at,long rev)=>e.At<at||e.At==at&&e.Revision<rev;
 static EntityId Id(string key)=>new("craft:"+ContractJson.Hash(Encoding.UTF8.GetBytes(key))[..28]);
 public static bool OwnIdUsed(ContractWorld w,EntityId id)=>Entries(w).Any(e=>e.Input.Id==id);
 public static CraftGroup[] Groups=>[new(new("craft:group/gun"),"試作・鉄砲鍛冶の一座",new("site:sakai"),CraftSkill.Gunsmith,10,"架空の職人集団。村の人口台帳とは別の職能集団10人。史実の国友・堺鍛冶の採録ではない"),new(new("craft:group/mining"),"試作・精錬の一座",new("site:kofu"),CraftSkill.Mining,10,"架空の外来職能集団10人"),new(new("craft:group/stone"),"試作・石工の一座",new("site:kyoto"),CraftSkill.Stonework,10,"架空の外来職能集団10人"),new(new("craft:group/foreign"),"試作・南蛮技術の一座",new("site:sakai"),CraftSkill.Foreign,10,"架空の外来職能集団10人")];
 public static CraftRecipe[] Recipes=>[new("gun",CraftSkill.Gunsmith,["iron"],[2],1,5,10,1,7*86400,WorksKind.Workshop),new("powder",CraftSkill.Gunsmith,["saltpeter","sulfur","charcoal"],[2,1,1],0,5,10,2,3*86400,WorksKind.Workshop),new("bullet",CraftSkill.Gunsmith,["lead"],[1],0,2,5,5,86400,WorksKind.Workshop),new("ore",CraftSkill.Mining,[],[],0,5,10,5,7*86400,WorksKind.Mine),new("gold",CraftSkill.Mining,["ore"],[5],0,5,10,1,7*86400,WorksKind.Mine),new("cut-stone",CraftSkill.Stonework,["rough-stone"],[10],0,5,10,5,7*86400,WorksKind.Workshop),new("cannon",CraftSkill.Foreign,["iron","charcoal"],[20,2],2,50,20,1,14*86400,WorksKind.Workshop)];
 public static string Name(string good)=>good switch{"iron"=>"鉄材","saltpeter"=>"硝石","sulfur"=>"硫黄","charcoal"=>"木炭","lead"=>"鉛","rough-stone"=>"原石","ore"=>"採掘鉱石","gold"=>"精錬金属","gun"=>"鉄砲","powder"=>"火薬","bullet"=>"玉","cut-stone"=>"切石","cannon"=>"大砲","wood"=>"木材",_=>throw new InvalidDataException("未定義の物資です")};
 public static string[] RawGoods=>["iron","saltpeter","sulfur","charcoal","lead","rough-stone"];
 public static long Price(string good)=>good switch{"iron"=>5,"saltpeter"=>8,"sulfur"=>6,"charcoal"=>2,"lead"=>5,"rough-stone"=>1,"gun"=>30,"powder"=>15,"bullet"=>2,"cut-stone"=>3,"gold"=>40,"cannon"=>150,"ore"=>2,"wood"=>4,_=>throw new InvalidDataException("物資の相場が未定義です")};
 public static bool ForeignAccess(ContractWorld w,EntityId actor,EntityId site,long at=long.MaxValue,long rev=long.MaxValue)=>Entries(w).Any(e=>e.Actor==actor&&e.Input.Site==site&&e.Input.Action==CraftAction.MeetMerchant&&Before(e,at,rev))&&(PermittedMission(w,site,at,rev)||Entries(w).Any(e=>e.Input.Action==CraftAction.ReturnVoyage&&e.Input.Site==site&&Before(e,at,rev))||Groups.Where(g=>g.Skill==CraftSkill.Foreign).Any(g=>Position(w,g.Id,at,rev) is {} p&&p.Site==site&&p.Owner!=null));
 public static long UnitPrice(ContractWorld w,EntityId site,string good,long at=long.MaxValue,long rev=long.MaxValue)=>Price(good)-(good is "saltpeter" or "lead"&&PermittedMission(w,site,at,rev)?1:0);
 public static RelationshipFact[] Facts(ContractWorld w,EntityId observer,EntityId subject)=>Entries(w).Where(e=>e.At<=w.ElapsedSeconds&&e.Actor==subject&&(e.Input.Action is CraftAction.JoinFaith or CraftAction.PermitMission)&&(observer==subject||observer==SocialWorld.Temple(w,e.Input.Site).Representative)).Select(e=>new RelationshipFact(observer,subject,e.Input.Id.Value,e.Input.Action==CraftAction.JoinFaith?"本人が現地で入信を選んだ。所属・所領とは別":(e.Input.Allow?"宣教師の布教許可を現地で取り交わした":"宣教師への布教許可の取りやめを現地で取り交わした"),e.At,e.At,0,0,0,0)).ToArray();
 internal static void Rewind(ContractWorld w,long at,long rev){if(w.Crafts!=null){var es=Entries(w).Where(e=>e.At<at||e.At==at&&e.Revision<=rev).ToArray();w.Crafts=es.Length==0?null:w.Crafts with{Entries=es};}}
 public static MissionOrganization Mission(EntityId site)=>new(Id("church/"+site.Value),Id("missionary/"+site.Value),site,"試作・宣教師の組織","港の小教会と代表者の試作定義。史実の宣教師や教会の採録ではない");
 static CraftEntry Source(ContractWorld w,EntityId id)=>Entries(w).Single(e=>e.Input.Id==id);
 static CraftEntry? Hire(ContractWorld w,EntityId group,long at,long rev)=>Entries(w).FirstOrDefault(e=>e.Input.Action==CraftAction.Hire&&e.Input.Reference==group&&e.Accepted&&Before(e,at,rev));
 public static CraftPosition Position(ContractWorld w,EntityId group,long at=long.MaxValue,long rev=long.MaxValue){at=Math.Min(at,w.ElapsedSeconds);var g=Groups.Single(g=>g.Id==group);var hired=Hire(w,group,at,rev);if(hired==null)return new(group,g.Home,null,null,null,false,null);var move=Entries(w).Where(e=>e.Input.Reference==group&&e.Accepted&&e.Input.Action is CraftAction.Hire or CraftAction.ResumeGroup&&Before(e,at,rev)).Last();if(move.Legs.Length==0)return new(group,move.Input.Destination,move.Input.Owner,move.Input.Destination,move.At,false,null);foreach(var leg in move.Legs){if(leg.StartAt>at)return new(group,RegionalCampaign.Site(leg.From),move.Input.Owner,move.Input.Destination,move.Legs[^1].EndAt,false,null);if(RegionalCampaign.BlockedAt(w,leg.Edge,leg.StartAt))return new(group,RegionalCampaign.Site(leg.From),move.Input.Owner,move.Input.Destination,null,true,leg.Edge);if(at<leg.EndAt)return new(group,null,move.Input.Owner,move.Input.Destination,move.Legs[^1].EndAt,false,null);}return new(group,move.Input.Destination,move.Input.Owner,move.Input.Destination,move.Legs[^1].EndAt,false,null);}
 public static CraftGroup[] LocalGroups(ContractWorld w,EntityId actor)=>SocialWorld.Site(w,actor) is {} site?Groups.Where(g=>Position(w,g.Id).Site==site).ToArray():[];
 public static long Stock(ContractWorld w,EntityId owner,EntityId site,string good,long at=long.MaxValue,long rev=long.MaxValue){at=Math.Min(at,w.ElapsedSeconds);long n=0;foreach(var e in Entries(w).Where(e=>e.Input.Owner==owner&&e.Input.Site==site&&Before(e,at,rev))){var i=e.Input;if(i.Action==CraftAction.Buy&&i.Good==good)n=checked(n+i.Quantity);if(i.Action==CraftAction.Sell&&i.Good==good)n=checked(n-i.Quantity);if(i.Action==CraftAction.Load&&i.Good==good)n=checked(n-i.Quantity);if(i.Action==CraftAction.Unload){var source=Source(w,i.Reference!.Value);if(source.Input.Good==good)n=checked(n+source.Input.Quantity);}
 if(i.Action==CraftAction.Produce){var recipe=Recipes.Single(r=>r.Good==i.Good);for(int k=0;k<recipe.Materials.Length;k++)if(recipe.Materials[k]==good)n=checked(n-recipe.Amounts[k]*i.Quantity);if(i.Good==good&&e.Due<=at)n=checked(n+recipe.Output*i.Quantity);}if(i.Action==CraftAction.LaunchVoyage&&i.Good==good&&good!="wood")n=checked(n-i.Quantity);if(i.Action==CraftAction.CancelVoyage){var launch=Source(w,i.Reference!.Value);if(launch.Input.Good==good&&good!="wood")n=checked(n+launch.Input.Quantity);}}return n;}
 public static CraftEntry[] Carried(ContractWorld w,EntityId actor,long at=long.MaxValue,long rev=long.MaxValue)=>Entries(w).Where(e=>e.Input.Action==CraftAction.Load&&e.Actor==actor&&Before(e,at,rev)&&!Entries(w).Any(u=>u.Input.Action==CraftAction.Unload&&u.Input.Reference==e.Input.Id&&Before(u,at,rev))).ToArray();
 public static int Mass(string good)=>good=="cannon"?100:good=="gun"?5:1;
 internal static long CarryingMass(ContractWorld w,EntityId actor,long rev)=>Carried(w,actor,long.MaxValue,rev).Sum(e=>e.Input.Quantity*Mass(e.Input.Good));
 internal static long WoodUsed(ContractWorld w,EntityId site,long at,long rev)=>Entries(w).Where(e=>e.Input.Site==site&&Before(e,at,rev)).Sum(e=>e.Wood-(e.Input.Action==CraftAction.CancelVoyage&&Source(w,e.Input.Reference!.Value).Input.Good=="wood"?Source(w,e.Input.Reference.Value).Input.Quantity:0));
 internal static (long At,long Revision,long Amount)[] RiceTransfers(ContractWorld w,EntityId site,long at,long rev)=>Entries(w).Where(e=>e.Input.Site==site&&Before(e,at,rev)&&e.Rice!=0).Select(e=>(e.At,e.Revision,-e.Rice)).ToArray();
 internal static long CashNet(ContractWorld w,EntityId site,long at,long rev)=>-Entries(w).Where(e=>e.Input.Site==site&&Before(e,at,rev)).Where(e=>e.Input.Action!=CraftAction.Hire).Sum(e=>e.Coins);
 internal static long PrivateNet(ContractWorld w,EntityId wallet,long at,long rev)=>-Entries(w).Where(e=>e.Input.Action==CraftAction.Hire&&Before(e,at,rev)&&NewGameWork.Wallet(e.Actor)==wallet).Sum(e=>e.Coins);
 internal static TreasuryEntry[] ProvisionPurchases(ContractWorld w,long at,long rev)=>Entries(w).Where(e=>e.Input.Action==CraftAction.Hire&&e.Accepted&&Before(e,at,rev)).Select(e=>new TreasuryEntry(new(e.Input.Id,TreasuryAction.Buy,e.Input.Site,null,50),e.Actor,e.At,e.Revision,null,null,new(Id("provisions/"+e.Input.Id.Value),e.Input.Id,e.Actor,new("org:market/"+e.Input.Site.Value.Replace(':','/')),e.Coins-e.Input.AnnualPay,e.At,e.Revision))).ToArray();
 internal static long ProvisionCost(ContractWorld w,long at,long rev)=>ProvisionPurchases(w,at,rev).Sum(e=>e.Payment!.Amount);
 public static long MerchantStock(ContractWorld w,EntityId site,string good,long at=long.MaxValue,long rev=long.MaxValue)=>(RawGoods.Contains(good)?100:0)-Entries(w).Where(e=>e.Input.Site==site&&e.Input.Action==CraftAction.Buy&&e.Input.Good==good&&Before(e,at,rev)).Sum(e=>e.Input.Quantity)+Entries(w).Where(e=>e.Input.Site==site&&e.Input.Action==CraftAction.Sell&&e.Input.Good==good&&Before(e,at,rev)).Sum(e=>e.Input.Quantity);
 public static long MerchantCash(ContractWorld w,EntityId site,long at=long.MaxValue,long rev=long.MaxValue)=>1000+Entries(w).Where(e=>e.Input.Site==site&&Before(e,at,rev)&&e.Input.Action is CraftAction.Buy or CraftAction.Sell or CraftAction.ReturnVoyage or CraftAction.CollectTradeDebt).Sum(e=>e.Coins);
 public static bool PermittedMission(ContractWorld w,EntityId site,long at=long.MaxValue,long rev=long.MaxValue)=>Entries(w).LastOrDefault(e=>e.Input.Site==site&&e.Input.Action==CraftAction.PermitMission&&Before(e,at,rev))?.Input.Allow==true;
 public static bool Christian(ContractWorld w,EntityId person)=>Entries(w).Any(e=>e.Actor==person&&e.Input.Action==CraftAction.JoinFaith);
 public static (long? Due,bool Waiting,bool Home) VoyageTiming(ContractWorld w,CraftEntry launch,long at){long delay=0;foreach(var leg in launch.Legs){long start=checked(leg.StartAt+delay);if(start>at)return(checked(launch.Due+delay),false,leg.From==NewGameWorld.Node(launch.Input.Site.Value));if(RegionalCampaign.BlockedAt(w,leg.Edge,start)){var open=w.Couriers!.Conditions.Where(c=>c.Edge==leg.Edge&&c.At>start&&c.At<=at&&!c.Blocked&&!RegionalCampaign.BlockedAt(w,c.Edge,c.At)).OrderBy(c=>c.At).FirstOrDefault();if(open==null)return(null,true,leg.From==NewGameWorld.Node(launch.Input.Site.Value));delay=checked(delay+open.At-start);}}return(checked(launch.Due+delay),false,false);}
 public static long TradeReceivable(ContractWorld w,EntityId voyage,long at=long.MaxValue,long rev=long.MaxValue){var launch=Source(w,voyage);if(!Entries(w).Any(e=>e.Input.Reference==voyage&&e.Input.Action==CraftAction.ReturnVoyage&&Before(e,at,rev)))return 0;return checked(launch.Input.Quantity*Price(launch.Input.Good)*2+Entries(w).Where(e=>e.Input.Reference==voyage&&e.Input.Action is CraftAction.ReturnVoyage or CraftAction.CollectTradeDebt&&Before(e,at,rev)).Sum(e=>e.Coins));}
 public static CraftVoyage[] Voyages(ContractWorld w)=>Entries(w).Where(e=>e.Input.Action==CraftAction.LaunchVoyage).Select(e=>{var end=Entries(w).LastOrDefault(a=>a.Input.Reference==e.Input.Id&&a.Input.Action is CraftAction.ReturnVoyage or CraftAction.CancelVoyage);var timing=VoyageTiming(w,e,w.ElapsedSeconds);return new CraftVoyage(e.Input.Id,e.Input.Reference!.Value,e.Input.Owner,e.Input.Site,e.At,timing.Due,end?.Input.Action==CraftAction.ReturnVoyage?(TradeReceivable(w,e.Input.Id)>0?"帰港・代金一部未払い":"帰港・決済済み"):end!=null?"取りやめ・荷戻し済み":timing.Waiting?"運休・寄港待機":w.ElapsedSeconds<e.Legs[0].StartAt?"出航準備":"航海中",e.Input.Good,e.Input.Quantity);}).ToArray();
 internal static long? NextBoundary(ContractWorld w,long target)=>Entries(w).SelectMany(e=>e.Legs.SelectMany(l=>new[]{l.StartAt,l.EndAt}).Append(e.Due)).Concat(Voyages(w).Where(v=>v.ReturnAt!=null).Select(v=>v.ReturnAt!.Value)).Where(t=>t>w.ElapsedSeconds&&t<=target).Order().Select(t=>(long?)t).FirstOrDefault();
}
